      out.write("\n");
      out.write("<script>\n");
      out.write("// Danh sách lý do riêng cho từng trạng thái kết thúc\n");
      out.write("const REASON_PRESETS = {\n");
      out.write("    'FULFILLED': [\n");
      out.write("        'Đã tuyển đủ số lượng chỉ tiêu (Headcount)',\n");
      out.write("        'Đã ký hợp đồng thử việc và tiếp nhận đủ ứng viên',\n");
      out.write("        'Tuyển vượt chỉ tiêu xuất sắc',\n");
      out.write("        'Ứng viên nội bộ đã được điều chuyển đáp ứng đủ yêu cầu',\n");
      out.write("        'Khác...'\n");
      out.write("    ],\n");
      out.write("    'PAUSED': [\n");
      out.write("        'Tạm dừng kế hoạch tuyển dụng quý này',\n");
      out.write("        'Đóng băng ngân sách tuyển dụng (Budget freeze)',\n");
      out.write("        'Chờ tái cơ cấu tổ chức / phòng ban chuyên môn',\n");
      out.write("        'Thay đổi yêu cầu năng lực vị trí cần chuẩn bị lại JD',\n");
      out.write("        'Khác...'\n");
      out.write("    ],\n");
      out.write("    'CANCELLED': [\n");
      out.write("        'Huỷ bỏ vị trí do thay đổi chiến lược kinh doanh',\n");
      out.write("        'Dự án bị huỷ bỏ hoặc thu hẹp quy mô hoạt động',\n");
      out.write("        'Chuyển giao vị trí sang đơn vị thành viên khác phụ trách',\n");
      out.write("        'Không còn nhu cầu tuyển dụng vị trí này',\n");
      out.write("        'Khác...'\n");
      out.write("    ]\n");
      out.write("};\n");
      out.write("\n");
      out.write("function onStatusChanged() {\n");
      out.write("    const selectedStatus = document.querySelector('input[name=\"terminalStatus\"]:checked').value;\n");
      out.write("    const reasonSelect = document.getElementById('closeReasonSelect');\n");
      out.write("    reasonSelect.innerHTML = '';\n");
      out.write("\n");
      out.write("    const list = REASON_PRESETS[selectedStatus] || ['Lý do khác...'];\n");
      out.write("    list.forEach(r => {\n");
      out.write("        const opt = document.createElement('option');\n");
      out.write("        opt.value = r;\n");
      out.write("        opt.textContent = r;\n");
      out.write("        reasonSelect.appendChild(opt);\n");
      out.write("    });\n");
      out.write("\n");
      out.write("    onReasonSelectChanged();\n");
      out.write("}\n");
      out.write("\n");
      out.write("function onReasonSelectChanged() {\n");
      out.write("    const select = document.getElementById('closeReasonSelect');\n");
      out.write("    const customWrapper = document.getElementById('customReasonWrapper');\n");
      out.write("    const customInput = document.getElementById('customReasonInput');\n");
      out.write("    const finalReason = document.getElementById('finalCloseReason');\n");
      out.write("\n");
      out.write("    if (select.value === 'Khác...') {\n");
      out.write("        customWrapper.style.display = 'block';\n");
      out.write("        finalReason.value = customInput.value.trim() || 'Lý do khác';\n");
      out.write("    } else {\n");
      out.write("        customWrapper.style.display = 'none';\n");
      out.write("        finalReason.value = select.value;\n");
      out.write("    }\n");
      out.write("}\n");
      out.write("\n");
      out.write("document.getElementById('customReasonInput').addEventListener('input', function() {\n");
      out.write("    if (document.getElementById('closeReasonSelect').value === 'Khác...') {\n");
      out.write("        document.getElementById('finalCloseReason').value = this.value.trim();\n");
      out.write("    }\n");
      out.write("});\n");
      out.write("\n");
      out.write("function openCloseModal(id, code, positionTitle) {\n");
      out.write("    document.getElementById('closeReqId').value = id;\n");
      out.write("    document.getElementById('closeModalSubtitle').textContent = code + ' - ' + positionTitle;\n");
      out.write("    \n");
      out.write("    // Reset form & radios\n");
      out.write("    document.querySelector('input[name=\"terminalStatus\"][value=\"FULFILLED\"]').checked = true;\n");
      out.write("    onStatusChanged();\n");
      out.write("    document.getElementById('closeNotes').value = '';\n");
      out.write("\n");
      out.write("    // Reset UI pipeline\n");
      out.write("    document.getElementById('pipelineLoading').style.display = 'block';\n");
      out.write("    document.getElementById('pipelineWarningBox').style.display = 'none';\n");
      out.write("    document.getElementById('pipelineSafeBox').style.display = 'none';\n");
      out.write("    document.getElementById('postingsStatusText').innerHTML = '<span class=\"spinner-border spinner-border-sm text-info me-1\" role=\"status\"></span> Đang kiểm tra tin tuyển dụng...';\n");
      out.write("\n");
